public class Question_04{public static void main(String[]x){int[]a={120,150,180,90,210,240,200,160,130,110,100,90,80,100,120,140,160,180,200,220,240,260,230,190};int k=3,s=0;for(int i=0;i<k;i++)s+=a[i];int best=s,start=0;for(int i=k;i<a.length;i++){s+=a[i]-a[i-k];if(s>best){best=s;start=i-k+1;}}System.out.println("Busiest 3-hour window: hours "+start+"-"+(start+2));System.out.println("Requests in window: "+best);System.out.println("Average RPM: "+best/3.0);}}